import { useState } from "react";
import { View, Text, Pressable, StyleSheet } from "react-native";

export default function App() {
  const [count, setCount] = useState(0);
  return (
    <View style={styles.wrap}>
      <Text style={styles.num}>{count}</Text>
      <Pressable style={styles.btn} onPress={() => setCount(count + 1)}>
        <Text style={styles.btnText}>Chạm để tăng</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { alignItems: "center", padding: 20 },
  num: { fontSize: 40, fontWeight: "bold" },
  btn: { backgroundColor: "#0f766e", padding: 12, borderRadius: 8 },
  btnText: { color: "white" },
});

