import { useState } from "react";
import { View, Text, Pressable } from "react-native";

export default function App() {
  const [on, setOn] = useState(false);
  return (
    <View>
      <Text testID="state">{on ? "ON" : "OFF"}</Text>
      <Pressable testID="sw" onPress={() => setOn(!on)}>
        <Text>Đổi</Text>
      </Pressable>
    </View>
  );
}
